"use client"

import { useState, useEffect } from "react"
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet"
import "leaflet/dist/leaflet.css"
import L from "leaflet"
import { Navigation } from "lucide-react"

const locations = [
  {
    id: 1,
    name: "Calapan City Hospital",
    category: "Hospital",
    lat: 13.4103,
    lng: 121.1803,
    address: "Gov. Antonio St, Calapan City, Oriental Mindoro",
    phone: "0917-123-4567",
  },
  {
    id: 2,
    name: "Calapan City Police Station",
    category: "Police",
    lat: 13.4142,
    lng: 121.1815,
    address: "City Hall Compound, Calapan City, Oriental Mindoro",
    phone: "0917-765-4321",
  },
  {
    id: 3,
    name: "Calapan City Fire Station",
    category: "Fire Dept",
    lat: 13.4115,
    lng: 121.1822,
    address: "San Vicente Central, Calapan City",
    phone: "0917-999-8888",
  },
]

const customIcon = new L.Icon({
  iconUrl: "https://cdn-icons-png.flaticon.com/512/684/684908.png",
  iconSize: [35, 35],
})

export default function InteractiveMap() {
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null)

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setUserLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude })
      })
    }
  }, [])

  return (
    <div className="w-full h-[600px] rounded-xl overflow-hidden shadow">
      <MapContainer
        center={[13.4103, 121.1803]}
        zoom={14}
        className="w-full h-full"
        scrollWheelZoom={true}
      >
        {/* Map Layer */}
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* User Location */}
        {userLocation && (
          <Marker
            position={[userLocation.lat, userLocation.lng]}
            icon={
              new L.Icon({
                iconUrl: "https://cdn-icons-png.flaticon.com/512/3177/3177361.png",
                iconSize: [35, 35],
              })
            }
          >
            <Popup>You are here</Popup>
          </Marker>
        )}

        {/* Establishments */}
        {locations.map((loc) => (
          <Marker key={loc.id} position={[loc.lat, loc.lng]} icon={customIcon}>
            <Popup>
              <div className="text-sm">
                <h3 className="font-bold text-gray-900">{loc.name}</h3>
                <p className="text-gray-600">{loc.address}</p>
                {loc.phone && <p className="text-gray-700 mt-1">☎ {loc.phone}</p>}

                {/* Get Directions */}
                {userLocation && (
                  <a
                    href={`https://www.google.com/maps/dir/${userLocation.lat},${userLocation.lng}/${loc.lat},${loc.lng}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="mt-2 inline-flex items-center gap-1 text-blue-600 font-medium"
                  >
                    <Navigation className="w-4 h-4" />
                    Get Directions
                  </a>
                )}
              </div>
            </Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  )
}
